  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/ai-reply-draft-assistant","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one structured event from the source system through a CtrlChecks webhook."}}},{"id":"ai_classify","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Classify and Draft","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Draft a careful reply to this customer email thread. Never claim it was sent. Return ONLY JSON: {\"route\":\"routine|review\",\"summary\":\"draft summary\",\"message\":\"draft reply\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Turns the incoming business context into structured fields the routing and message steps can trust."}}},{"id":"js_parse_ai","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse AI JSON","category":"data","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || \"{}\";\n  const match = String(text).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} 