-- Company Policy Chatbot (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000010$tpl$, $tpl$Company Policy Chatbot$tpl$, $tpl$Let employees submit policy questions through a form, query Qdrant policy context, and return an HR-safe answer by email.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Request","category":"triggers","config":{"formTitle":"Company Policy Chatbot","fields":[{"key":"employeeEmail","label":"Employee Email","type":"email","required":true},{"key":"question","label":"Question","type":"text","required":true},{"key":"department","label":"Department","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request through the native Form trigger, which is allowed by the template gate."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.sessionId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_qdrant_policy","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Database","type":"qdrant","label":"Query Policy Collection","category":"data","config":{"operation":"query","url":"https://REPLACE_WITH_QDRANT_ENDPOINT","collection":"company_policy","vector":"{{input.embedding}}","limit":5},"notes":{"family":"Data","what":"Query, upsert, and delete vectors in Qdrant collections for semantic search, RAG, recommendations, and AI memory workflows.","overview":"Search, upsert, and delete embedding vectors in Qdrant collections. The UI value for Query/Search is now query, matching the runtime; the old search/get_collection values were not supported by the executor.","tips":["Qdrant Cloud usually requires an API key; self-hosted local Qdrant may not.","Vector length must match the collection vector size.","Upsert can auto-create a missing collection with Cosine distance when Vector is supplied.","Always set Point ID for upsert; otherwise the current runtime can fall back to point 1.","Use Include Payload when downstream AI steps need document titles, URLs, or IDs."],"docsHref":"/docs/nodes/qdrant","why":"Preserves the policy-RAG design while replacing the unsupported Slack trigger with native form intake."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are the HR policy assistant. Answer only from policy context. For pay, disciplinary matters, or individual leave balances, route to HR. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"gmail_policy_answer","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Mail","type":"google_gmail","label":"Email Policy Answer","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.employeeEmail}}","subject":"Policy assistant response","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the policy answer to the employee without relying on an unsupported Slack trigger."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_intake_memory_context","source":"form_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_form_intake_tool_qdrant_policy","source":"form_intake","target":"tool_qdrant_policy"},{"id":"e_4_tool_qdrant_policy_ai_agent","source":"tool_qdrant_policy","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_form_intake_ai_agent","source":"form_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_gmail_policy_answer","source":"js_parse_agent","target":"gmail_policy_answer"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$policy$tpl$,$tpl$qdrant$tpl$,$tpl$hr$tpl$,$tpl$form$tpl$,$tpl$ai-agent$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
