  $tpl$93000000-0000-4000-8000-000000000027$tpl$, $tpl$Competitor Price Monitoring Agent$tpl$, $tpl$Fetch competitor product pages, compare against a price-history sheet, log changes, and alert Slack.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"schedule_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Scheduled Run","category":"triggers","config":{"cron":"0 3 * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs the agent on a predictable schedule so the workflow does not depend on an unsupported vendor trigger."}}},{"id":"tool_competitor_page","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Globe","type":"http_request","label":"Fetch Competitor Page","category":"http_api","config":{"url":"https://example.com/competitor-products","method":"GET","timeout":10000},"notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Fetches current competitor page content for extraction."}}},{"id":"tool_price_history","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Table","type":"google_sheets","label":"Read Price History","category":"data","config":{"operation":"read","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Price History!A:Z"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Gives the agent last-known prices for comparison."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Extract current prices and compare them against price history. Return hasChanges true when any SKU changed, plus summary and rowsToAppend as text. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"sheets_log_price_change","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Table","type":"google_sheets","label":"Append Price Changes","category":"data","config":{"operation":"append","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Price History!A:Z","values":"{{input.rowsToAppend}}"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Writes the detected price changes to the price-history sheet as one append operation."}}},{"id":"if_price_changed","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Price Changed?","category":"logic","config":{"conditions":[{"field":"$json.hasChanges","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only notifies the pricing channel when there is an actual change."}}},{"id":"slack_price_alert","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Pricing Team","category":"output","config":{"channel":"#pricing-alerts","message":"Competitor price change: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Alerts pricing when the agent detects meaningful changes."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_intake_tool_competitor_page","source":"schedule_intake","target":"tool_competitor_page"},{"id":"e_2_tool_competitor_page_ai_agent","source":"tool_competitor_page","target":"ai_agent","targetHandle":"tool"},{"id":"e_3_schedule_intake_tool_price_history","source":"schedule_intake","target":"tool_price_history"},{"id":"e_4_tool_price_history_ai_agent","source":"tool_price_history","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_schedule_intake_ai_agent","source":"schedule_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_sheets_log_price_change","source":"js_parse_agent","target":"sheets_log_price_change"},{"id":"e_8_sheets_log_price_change_if_price_changed","source":"sheets_log_price_change","target":"if_price_changed"},{"id":"e_9_if_price_changed_slack_price_alert","source":"if_price_changed","target":"slack_price_alert","sourceHandle":"true"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
