-- CRM Data Cleanup Assistant (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$91000000-0000-4000-8000-000000000014$tpl$, $tpl$CRM Data Cleanup Assistant$tpl$, $tpl$Find one CRM contact needing cleanup, detect missing fields, update the CRM, and notify ops when human research is needed.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"schedule_crm_cleanup","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check CRM Records","category":"triggers","config":{"cron":"*/20 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs continuously but lightly, cleaning one record per pass."}}},{"id":"hubspot_read_contact","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Find Contact to Clean","category":"crm","config":{"resource":"contact","operation":"list","properties":{"limit":1}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Uses the real CRM node so the template works against the system sales teams use."}}},{"id":"js_detect_missing_crm","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Detect Missing Fields","category":"data","config":{"code":"const contact = (input.results || input.contacts || [])[0] || input;\nconst missing = [\"email\", \"firstname\", \"company\"].filter((field) => !contact[field]);\nreturn { ...input, contactId: contact.id || \"\", missing, needsResearch: missing.length > 0, missingText: missing.join(\", \") || \"None\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Finds the exact fields missing from the contact record."}}},{"id":"if_crm_missing","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Cleanup?","category":"logic","config":{"conditions":[{"field":"$json.needsResearch","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only records with missing required fields create work for ops."}}},{"id":"slack_crm_research","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Ask Ops to Research","category":"output","config":{"channel":"#revops","message":"CRM contact needs cleanup. Missing: {{input.missingText}}. Contact ID: {{input.contactId}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes incomplete records to RevOps for human research."}}},{"id":"hubspot_mark_reviewed","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Mark Reviewed","category":"crm","config":{"resource":"contact","operation":"update","id":"{{input.contactId}}","properties":{"ctrlchecks_reviewed":"true"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Marks the contact as reviewed so it can be excluded from future cleanup passes."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_crm_cleanup_hubspot_read_contact","source":"schedule_crm_cleanup","target":"hubspot_read_contact"},{"id":"e_2_hubspot_read_contact_js_detect_missing_crm","source":"hubspot_read_contact","target":"js_detect_missing_crm"},{"id":"e_3_js_detect_missing_crm_if_crm_missing","source":"js_detect_missing_crm","target":"if_crm_missing"},{"id":"e_4_if_crm_missing_slack_crm_research","source":"if_crm_missing","target":"slack_crm_research","sourceHandle":"true"},{"id":"e_5_if_crm_missing_hubspot_mark_reviewed","source":"if_crm_missing","target":"hubspot_mark_reviewed","sourceHandle":"false"},{"id":"e_6_slack_crm_research_hubspot_mark_reviewed","source":"slack_crm_research","target":"hubspot_mark_reviewed"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  23, ARRAY[$tpl$crm$tpl$,$tpl$hubspot$tpl$,$tpl$cleanup$tpl$,$tpl$operations$tpl$,$tpl$slack$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$CRM Data Cleanup Assistant$tpl$,
    description          = $tpl$Find one CRM contact needing cleanup, detect missing fields, update the CRM, and notify ops when human research is needed.$tpl$,
    category             = $tpl$Sales, Support & Internal Operations$tpl$,
    nodes                = $tpl$[{"id":"schedule_crm_cleanup","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check CRM Records","category":"triggers","config":{"cron":"*/20 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs continuously but lightly, cleaning one record per pass."}}},{"id":"hubspot_read_contact","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Find Contact to Clean","category":"crm","config":{"resource":"contact","operation":"list","properties":{"limit":1}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Uses the real CRM node so the template works against the system sales teams use."}}},{"id":"js_detect_missing_crm","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Detect Missing Fields","category":"data","config":{"code":"const contact = (input.results || input.contacts || [])[0] || input;\nconst missing = [\"email\", \"firstname\", \"company\"].filter((field) => !contact[field]);\nreturn { ...input, contactId: contact.id || \"\", missing, needsResearch: missing.length > 0, missingText: missing.join(\", \") || \"None\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Finds the exact fields missing from the contact record."}}},{"id":"if_crm_missing","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Cleanup?","category":"logic","config":{"conditions":[{"field":"$json.needsResearch","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only records with missing required fields create work for ops."}}},{"id":"slack_crm_research","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Ask Ops to Research","category":"output","config":{"channel":"#revops","message":"CRM contact needs cleanup. Missing: {{input.missingText}}. Contact ID: {{input.contactId}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes incomplete records to RevOps for human research."}}},{"id":"hubspot_mark_reviewed","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Mark Reviewed","category":"crm","config":{"resource":"contact","operation":"update","id":"{{input.contactId}}","properties":{"ctrlchecks_reviewed":"true"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Marks the contact as reviewed so it can be excluded from future cleanup passes."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_schedule_crm_cleanup_hubspot_read_contact","source":"schedule_crm_cleanup","target":"hubspot_read_contact"},{"id":"e_2_hubspot_read_contact_js_detect_missing_crm","source":"hubspot_read_contact","target":"js_detect_missing_crm"},{"id":"e_3_js_detect_missing_crm_if_crm_missing","source":"js_detect_missing_crm","target":"if_crm_missing"},{"id":"e_4_if_crm_missing_slack_crm_research","source":"if_crm_missing","target":"slack_crm_research","sourceHandle":"true"},{"id":"e_5_if_crm_missing_hubspot_mark_reviewed","source":"if_crm_missing","target":"hubspot_mark_reviewed","sourceHandle":"false"},{"id":"e_6_slack_crm_research_hubspot_mark_reviewed","source":"slack_crm_research","target":"hubspot_mark_reviewed"}]$tpl$::jsonb,
