  $tpl$92000000-0000-4000-8000-000000000017$tpl$, $tpl$CRM Org Enrichment on Demand$tpl$, $tpl$Enrich one company from a static API, summarize firmographics, update HubSpot, and notify RevOps.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Intake Details","category":"triggers","config":{"formTitle":"CRM Org Enrichment on Demand","fields":[{"key":"companyName","label":"Company Name","type":"text","required":true},{"key":"domain","label":"Domain","type":"text","required":true},{"key":"hubspotContactId","label":"Hubspot Contact Id","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request so the workflow handles a single record per run."}}},{"id":"http_enrich","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Globe","type":"http_request","label":"Fetch External Context","category":"http_api","config":{"url":"https://api.example.com/company?domain={{input.domain}}","method":"GET","timeout":10000},"notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Fetches static API or website context needed for the assessment; credentials stay in the connected service, not in the template."}}},{"id":"ai_classify","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Classify and Draft","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Summarize firmographic enrichment for {{input.companyName}} from this API response: {{input.body}}. Return ONLY JSON: {\"route\":\"routine\",\"summary\":\"firmographic summary\",\"message\":\"CRM note\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Turns the incoming business context into structured fields the routing and message steps can trust."}}},{"id":"js_parse_ai","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse AI JSON","category":"data","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || \"{}\";\n  const match = String(text).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nreturn { ...input, ...parsed };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Parses the AI JSON into real workflow fields before any branch reads those fields."}}},{"id":"if_route","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Attention?","category":"logic","config":{"conditions":[{"field":"$json.route","operator":"equals","value":"review"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Splits high-attention work from routine handling using one explicit comparison."}}},{"id":"slack_review","type":"custom","position":{"x":1700,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Notify Team","category":"output","config":{"channel":"#revops","message":"CRM Org Enrichment on Demand: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the exception in front of the team that can act on it."}}},{"id":"gmail_routine","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Send Routine Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"REPLACE_WITH_REVOPS_EMAIL","subject":"CRM enrichment complete","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the routine response or acknowledgement without requiring a manual handoff."}}},{"id":"store_result","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Log Result","category":"data","config":{"baseId":"","tableId":"OrgEnrichment","operation":"create","fields":{"Name":"{{input.name}}","Email":"{{input.email}}","Summary":"{{input.summary}}","Route":"{{input.route}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Logs the assessment so the team has a durable queue outside the execution log."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_intake_http_enrich","source":"form_intake","target":"http_enrich"},{"id":"e_2_http_enrich_ai_classify","source":"http_enrich","target":"ai_classify"},{"id":"e_3_ai_classify_js_parse_ai","source":"ai_classify","target":"js_parse_ai"},{"id":"e_4_js_parse_ai_if_route","source":"js_parse_ai","target":"if_route"},{"id":"e_5_if_route_slack_review","source":"if_route","target":"slack_review","sourceHandle":"true"},{"id":"e_6_if_route_gmail_routine","source":"if_route","target":"gmail_routine","sourceHandle":"false"},{"id":"e_7_slack_review_store_result","source":"slack_review","target":"store_result"},{"id":"e_8_gmail_routine_store_result","source":"gmail_routine","target":"store_result"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
