  $tpl$[{"id":"schedule_churn_check","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Check Customer Risk","category":"triggers","config":{"cron":"*/30 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs on a timer because churn signals appear in account data over time."}}},{"id":"airtable_read_customer","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One Customer","category":"data","config":{"baseId":"","tableId":"Customers","operation":"read","filterByFormula":"AND({Status}='Active', {ChurnCheckedAt}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Selects one active customer that has not been checked yet."}}},{"id":"ai_churn_score","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Score Churn Risk","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Score churn risk for this customer record: {{input.records}}. Return ONLY JSON: {\"risk\":\"low|medium|high\",\"reason\":\"short reason\",\"nextAction\":\"specific action\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Uses account context to judge risk and recommend the next action."}}},{"id":"js_parse_churn","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Risk Score","category":"data","config":{"code":"const rec = (input.records || [])[0];\nlet parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nconst f = rec?.fields || {};\nreturn { ...input, recordId: rec?.id || \"\", customerName: f.Name || \"customer\", ownerChannel: f.OwnerChannel || \"#customer-success\", risk: parsed.risk || \"medium\", reason: parsed.reason || \"\", nextAction: parsed.nextAction || \"\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Combines the Airtable record ID with the parsed AI risk fields."}}},{"id":"if_high_churn","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"High Churn Risk?","category":"logic","config":{"conditions":[{"field":"$json.risk","operator":"equals","value":"high"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Only high-risk accounts interrupt the account team."}}},{"id":"slack_churn_alert","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Account Manager","category":"output","config":{"channel":"{{input.ownerChannel}}","message":"High churn risk: {{input.customerName}}\nReason: {{input.reason}}\nNext action: {{input.nextAction}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes the alert to the owner responsible for saving the account."}}},{"id":"airtable_mark_churn_checked","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Checked","category":"data","config":{"baseId":"","tableId":"Customers","operation":"update","recordId":"{{input.recordId}}","fields":{"ChurnCheckedAt":"Checked"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Prevents the same customer from being rescored on every poll."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_churn_check_airtable_read_customer","source":"schedule_churn_check","target":"airtable_read_customer"},{"id":"e_2_airtable_read_customer_ai_churn_score","source":"airtable_read_customer","target":"ai_churn_score"},{"id":"e_3_ai_churn_score_js_parse_churn","source":"ai_churn_score","target":"js_parse_churn"},{"id":"e_4_js_parse_churn_if_high_churn","source":"js_parse_churn","target":"if_high_churn"},{"id":"e_5_if_high_churn_slack_churn_alert","source":"if_hi