-- Domain Age & Reputation Screener (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$92000000-0000-4000-8000-000000000002$tpl$, $tpl$Domain Age & Reputation Screener$tpl$, $tpl$Screen one applicant domain through a static reputation API, score the risk, and alert compliance when review is needed.$tpl$, $tpl$Business Verification & Compliance$tpl$,
  $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Intake Details","category":"triggers","config":{"formTitle":"Domain Age & Reputation Screener","fields":[{"key":"businessName","label":"Business Name","type":"text","required":true},{"key":"email","label":"Email","type":"email","required":true},{"key":"domain","label":"Domain","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request so the workflow handles a single record per run."}}},{"id":"http_enrich","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Globe","type":"http_request","label":"Fetch External Context","category":"http_api","config":{"url":"https://api.example.com/domain/reputation?domain={{input.domain}}","method":"GET","timeout":10000},"notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Fetches 