) VALUES (
  $tpl$93000000-0000-4000-8000-000000000020$tpl$, $tpl$Expense Receipt Tracker Agent$tpl$, $tpl$Extract receipt details from Telegram submissions, append them to an expense sheet, and confirm in Telegram.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/expense-receipt-tracker-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.userId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_expense_sheet","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Table","type":"google_sheets","label":"Read Recent Expenses","category":"data","config":{"operation":"read","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Expenses!A:Z"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Lets the agent compare against recent expenses when extracting a new receipt."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Extract merchant, amount, currency, category, and date from this receipt text or payload. Return a concise confirmation message. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"user","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"sheets_append_expense","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Table","type":"google_sheets","label":"Append Expense Row","category":"data","config":{"operation":"append","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Expenses!A:F","values":"{{input.summary}}"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Stores the structured receipt in the shared expense sheet."}}},{"id":"telegram_expense_ack","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Send","type":"telegram","label":"Confirm in Telegram","category":"output","config":{"chatId":"{{input.chatId}}","text":"{{input.message}}"},"notes":{"family":"Communication","what":"Sends messages to a Telegram chat or bot conversation","overview":"Send Telegram text messages, media URLs, and message edits through a saved Telegram Bot Token connection. Use it for Telegram bot replies, support alerts, report delivery, approval buttons, and status updates.","tips":["Create the bot with @BotFather, then save the Telegram Bot Token in Connections","Use {{$json.chatId}} and {{$json.messageId}} from Telegram Trigger to reply in the same chat","Choose send_message for text, send_photo plus Media URL for images, and edit_message when updating a previous bot message","For media message types, use a public HTTPS Media URL that Telegram can fetch without signing in","Connect downstream service accounts separately; Telegram credentials only authorize Telegram sends"],"docsHref":"/docs/nodes/telegram","why":"Confirms the logged receipt back to the employee."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_webhook_intake_memory_context","source":"webhook_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_webhook_intake_tool_expense_sheet","source":"webhook_intake","target":"tool_expense_sheet"},{"id":"e_4_tool_expense_sheet_ai_agent","source":"tool_expense_sheet","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_sheets_append_expense","source":"js_parse_agent","target":"sheets_append_expense"},{"id":"e_8_sheets_append_expense_telegram_expense_ack","source":"sheets_append_expense","target":"telegram_expense_ack"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$telegram$tpl$,$tpl$expenses$tpl$,$tpl$google-sheets$tpl$,$tpl$finance$tpl$,$tpl$ai-agent$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
