    edges                = $tpl$[{"id":"e_1_webhook_intake_tool_pr_diff","source":"webhook_intake","target":"tool_pr_diff"},{"id":"e_2_tool_pr_diff_ai_agent","source":"tool_pr_diff","target":"ai_agent","targetHandle":"tool"},{"id":"e_3_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_4_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_5_js_parse_agent_postgres_log_pr_review","source":"js_parse_agent","target":"postgres_log_pr_review"},{"id":"e_6_postgres_log_pr_review_slack_pr_summary","source":"postgres_log_pr_review","target":"slack_pr_summary"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 20,
