-- Google Calendar Scheduling Assistant (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000006$tpl$, $tpl$Google Calendar Scheduling Assistant$tpl$, $tpl$Let a user ask for scheduling help in chat, check calendar context, and draft a booking confirmation for approval-safe calendar handling.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"chat_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"chat_trigger","label":"Receive Chat Message","category":"triggers","config":{},"notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Starts the agent from one chat message and preserves the session data for replies."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.sessionId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_calendar_read","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Calendar","type":"google_calendar","label":"Read Calendar Availability","category":"data","config":{"resource":"event","operation":"list","calendarId":"primary","maxResults":10},"notes":{"family":"Data","what":"Read, create, update, or delete events in your Google Calendar","overview":"Create, list, update, or delete Google Calendar events. Manage your calendar programmatically. Runtime also supports get, quickAdd, and move for events, plus non-event resources, when set directly in workflow JSON.","tips":["Use \"primary\" for main calendar","Times must be ISO 8601 format (UTC) â€” Start Time/End Time are converted automatically","The new/updated event ID is returned as id, not eventId","List returns events in the Time Min/Time Max window, with no date filtering by default"],"docsHref":"/docs/nodes/google_calendar","why":"Google Calendar is verified working; this read context lets the agent reason about availability before drafting a booking."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are a scheduling assistant. Check availability context, propose a final time, and set readyToBook true only when the user has clearly confirmed. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"write_and_destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"if_ready_to_book","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Ready to Book?","category":"logic","config":{"conditions":[{"field":"$json.readyToBook","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Prevents calendar writes until the agent sees explicit confirmation."}}},{"id":"calendar_create_event","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Calendar","type":"google_calendar","label":"Create Calendar Event","category":"data","config":{"resource":"event","operation":"create","calendarId":"primary","summary":"{{input.summary}}","start":"{{input.startTime}}","end":"{{input.endTime}}"},"notes":{"family":"Data","what":"Read, create, update, or delete events in your Google Calendar","overview":"Create, list, update, or delete Google Calendar events. Manage your calendar programmatically. Runtime also supports get, quickAdd, and move for events, plus non-event resources, when set directly in workflow JSON.","tips":["Use \"primary\" for main calendar","Times must be ISO 8601 format (UTC) â€” Start Time/End Time are converted automatically","The new/updated event ID is returned as id, not eventId","List returns events in the Time Min/Time Max window, with no date filtering by default"],"docsHref":"/docs/nodes/google_calendar","why":"Creates the confirmed calendar event using the verified Google Calendar action node."}}},{"id":"chat_schedule_reply","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Send","type":"chat_send","label":"Reply in Chat","category":"output","config":{"message":"{{input.message}}"},"notes":{"family":"Database","what":"Sends a reply in a chat conversation — works with a chat trigger to create a bot","overview":"","tips":[],"docsHref":null,"why":"Confirms the proposed or booked time in the same chat session."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_chat_intake_memory_context","source":"chat_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_chat_intake_tool_calendar_read","source":"chat_intake","target":"tool_calendar_read"},{"id":"e_4_tool_calendar_read_ai_agent","source":"tool_calendar_read","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_chat_intake_ai_agent","source":"chat_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_if_ready_to_book","source":"js_parse_agent","target":"if_ready_to_book"},{"id":"e_8_if_ready_to_book_calendar_create_event","source":"if_ready_to_book","target":"calendar_create_event","sourceHandle":"true"},{"id":"e_9_if_ready_to_book_chat_schedule_reply","source":"if_ready_to_book","target":"chat_schedule_reply","sourceHandle":"false"},{"id":"e_10_calendar_create_event_chat_schedule_reply","source":"calendar_create_event","target":"chat_schedule_reply"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$calendar$tpl$,$tpl$scheduling$tpl$,$tpl$chat$tpl$,$tpl$ai-agent$tpl$,$tpl$google$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
