-- Inbound Email Sales Agent (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000013$tpl$, $tpl$Inbound Email Sales Agent$tpl$, $tpl$Receive sales-email payloads by webhook, score intent with Salesforce context, and alert reps for hot leads.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/inbound-email-sales-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.threadId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_salesforce_lookup","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Cloud","type":"salesforce","label":"Search Salesforce Opportunities","category":"crm","config":{"operation":"query","soql":"SELECT Id, Name, StageName FROM Opportunity WHERE ContactEmail__c = '{{input.from}}' LIMIT 5"},"notes":{"family":"CRM","what":"Read or write records in Salesforce — leads, contacts, opportunities, and more","overview":"Interact with Salesforce CRM using SOQL queries, SOSL search, or CRUD/upsert/bulk operations. Supports standard objects (Account, Contact, Lead, Opportunity, etc.) and custom objects. All 11 dropdown operations are real and implemented - one of the most accurately-matched CRM nodes in this product. Instance URL is not vault-backed and must be typed on every node even after connecting Salesforce.","tips":[],"docsHref":"/docs/nodes/salesforce","why":"Keeps the source Salesforce history lookup while replacing the unsupported Gmail trigger with webhook intake."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Read this inbound sales email. Score intent hot/warm/cold, draft a reply, and include opportunity_id if context provides one. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"if_hot_lead","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Hot Lead?","category":"logic","config":{"conditions":[{"field":"$json.tier","operator":"equals","value":"hot"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Hot leads need immediate human follow-up while other replies can be logged silently."}}},{"id":"slack_hot_lead","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Alert Sales Rep","category":"output","config":{"channel":"#hot-leads","message":"Hot sales email from {{input.from}}: {{input.summary}}\nDraft: {{input.message}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Alerts reps only for high-intent sales replies."}}},{"id":"salesforce_log_activity","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Cloud","type":"salesforce","label":"Log Sales Activity","category":"crm","config":{"operation":"create","resource":"Task","fields":{"Subject":"Inbound email handled by CtrlChecks","Description":"{{input.summary}}"}},"notes":{"family":"CRM","what":"Read or write records in Salesforce — leads, contacts, opportunities, and more","overview":"Interact with Salesforce CRM using SOQL queries, SOSL search, or CRUD/upsert/bulk operations. Supports standard objects (Account, Contact, Lead, Opportunity, etc.) and custom objects. All 11 dropdown operations are real and implemented - one of the most accurately-matched CRM nodes in this product. Instance URL is not vault-backed and must be typed on every node even after connecting Salesforce.","tips":[],"docsHref":"/docs/nodes/salesforce","why":"Logs every inbound sales interaction in Salesforce after classification."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_webhook_intake_memory_context","source":"webhook_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_webhook_intake_tool_salesforce_lookup","source":"webhook_intake","target":"tool_salesforce_lookup"},{"id":"e_4_tool_salesforce_lookup_ai_agent","source":"tool_salesforce_lookup","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_if_hot_lead","source":"js_parse_agent","target":"if_hot_lead"},{"id":"e_8_if_hot_lead_slack_hot_lead","source":"if_hot_lead","target":"slack_hot_lead","sourceHandle":"true"},{"id":"e_9_if_hot_lead_salesforce_log_activity","source":"if_hot_lead","target":"salesforce_log_activity","sourceHandle":"false"},{"id":"e_10_slack_hot_lead_salesforce_log_activity","source":"slack_hot_lead","target":"salesforce_log_activity"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$sales-email$tpl$,$tpl$salesforce$tpl$,$tpl$webhook$tpl$,$tpl$slack$tpl$,$tpl$ai-agent$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
