  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/incident-triage-sla-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"tool_incident_history","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Bug","type":"jira","label":"Search Incident History","category":"devops","config":{"operation":"search_issues","jql":"project = OPS AND text ~ '{{input.alertName}}'"},"notes":{"family":"DevOps","what":"Creates or updates issues, sprints, and projects in Jira","overview":"Create, read, update, delete, search, transition, and comment on Jira Cloud issues. The node uses a Jira API-token connection and preserves incoming fields while adding operation-specific Jira fields.","tips":["Domain is the Atlassian host such as acme.atlassian.net; the runtime also accepts baseUrl aliases","Email and API token usually come from the saved Jira connection","Create Issue requires projectKey and summary","Search Issues requires jql and calls the Jira Cloud /rest/api/3/search/jql endpoint","Description and comments are converted to Atlassian Document Format before sending"],"docsHref":"/docs/nodes/jira","why":"Uses Jira as read-side incident context before the agent assigns severity."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"mo