-- Lead Qualification & Nurturing Agent (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000012$tpl$, $tpl$Lead Qualification & Nurturing Agent$tpl$, $tpl$Use a native form intake for BANT qualification, update HubSpot, and send tier-appropriate nurture email.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Request","category":"triggers","config":{"formTitle":"Lead Qualification & Nurturing Agent","fields":[{"key":"name","label":"Name","type":"text","required":true},{"key":"email","label":"Email","type":"email","required":true},{"key":"company","label":"Company","type":"text","required":true},{"key":"budget","label":"Budget","type":"text","required":true},{"key":"timeline","label":"Timeline","type":"text","required":true},{"key":"need","label":"Need","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request through the native Form trigger, which is allowed by the template gate."}}},{"id":"tool_hubspot_contact","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Read Existing HubSpot Contact","category":"crm","config":{"resource":"contact","operation":"get","properties":{"email":"{{input.email}}"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Replaces Typeform Trigger with Form while preserving the HubSpot history lookup."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Score this lead 0-100 from Budget, Authority, Need, and Timeline. Return score, tier hot/warm/cold, reasoning, and follow-up copy. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"hubspot_upsert_lead","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Update HubSpot Lead","category":"crm","config":{"resource":"contact","operation":"create","properties":{"email":"{{input.email}}","firstname":"{{input.name}}","company":"{{input.company}}","lead_score":"{{input.score}}","lead_tier":"{{input.tier}}"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Writes the score and tier to the CRM exactly once after the agent decides."}}},{"id":"gmail_nurture_lead","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Mail","type":"google_gmail","label":"Send Nurture Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.email}}","subject":"Thanks for your interest","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the tier-appropriate follow-up to the lead."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_intake_tool_hubspot_contact","source":"form_intake","target":"tool_hubspot_contact"},{"id":"e_2_tool_hubspot_contact_ai_agent","source":"tool_hubspot_contact","target":"ai_agent","targetHandle":"tool"},{"id":"e_3_form_intake_ai_agent","source":"form_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_4_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_5_js_parse_agent_hubspot_upsert_lead","source":"js_parse_agent","target":"hubspot_upsert_lead"},{"id":"e_6_hubspot_upsert_lead_gmail_nurture_lead","source":"hubspot_upsert_lead","target":"gmail_nurture_lead"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
