    category             = $tpl$AI Agent$tpl$,
    nodes                = $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Request","category":"triggers","config":{"formTitle":"Lead Qualification & Nurturing Agent","fields":[{"key":"name","label":"Name","type":"text","required":true},{"key":"email","label":"Email","type":"email","required":true},{"key":"company","label":"Company","type":"text","required":true},{"key":"budget","label":"Budget","type":"text","required":true},{"key":"timeline","label":"Timeline","type":"text","required":true},{"key":"need","label":"Need","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request through the native Form trigger, which is allowed by the template gate."}}},{"id":"tool_hubspot_contact","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Zap","type":"hubspot","label":"Read Existing HubSpot Contact","category":"crm","config":{"resource":"contact","operation":"get","properties":{"email":"{{input.email}}"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot C