ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$LinkedIn Outreach Personalization Agent$tpl$,
    description          = $tpl$Read one outreach lead from Sheets, draft a personalized LinkedIn note, send it through LinkedIn, and mark the row handled.$tpl$,
    category             = $tpl$AI Agent$tpl$,
    nodes                = $tpl$[{"id":"schedule_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Scheduled Run","category":"triggers","config":{"cron":"0 9 * * 1-5","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs the agent on a predictable schedule so the workflow does not depend on an unsupported vendor trigger."}}},{"id":"tool_outreach_queue","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Table","type":"google_sheets","label":"Read Outreach Queue","category":"data","config":{"operation":"read","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Outreach Queue!A:Z"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Feeds the agent one queue of leads to personalize against."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Write a short LinkedIn connection note under 300 characters using profile and company clues from the outreach queue. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"linkedin_send_note","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Linkedin","type":"linkedin","label":"Send LinkedIn Note","category":"output","config":{"operation":"create_post","text":"{{input.message}}"},"notes":{"family":"Communication","what":"Posts updates to LinkedIn or reads professional network content","overview":"Use LinkedIn OAuth to get your profile, read recent posts, publish personal/company/article/media posts, delete posts, or dry-run a simulated API request before publishing.","tips":["Connect LinkedIn in Connections; accessToken is only a legacy fallback","Get My Profile verifies OAuth and returns profile.personUrn","Create Post (Media) requires a public Media URL; text can be empty only for media posts","Company Page posts require Organization ID and page/admin permission","Dry Run returns simulatedRequest and does not publish, upload, or delete"],"docsHref":"/docs/nodes/linkedin","why":"Keeps the verified LinkedIn leg from the source marketing/sales pattern."}}},{"id":"slack_outreach_log","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Log Outreach","category":"output","config":{"channel":"#sales","message":"LinkedIn outreach drafted/sent: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Gives sales a visible audit trail for automated outreach."}}}]$tpl$::jsonb,
