    nodes                = $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/meeting-notes-action-item-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"ai_agent","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Summarize this meeting transcript into key decisions, a discussion summary, and one formatted action-items block with owners and due dates. Do not return an array. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"google_doc_meeting_notes","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"FileText","type":"google_doc","label":"Create Meeting Notes Doc","category":"data","config":{"operation":"create","title":"Meeting Notes - {{input.meetingTitle}}","content":"{{input.message}}"},"notes":{"family":"Data","what":"Read from or write to a Google Doc — create documents or update them automatically","overview":"Read, overwrite (write), create, or append content in Google Docs. Read extracts plain text only; the Output Format \"Markdown\" option is currently a label and does not actually convert formatting.","tips":["Get Document ID from the Google Docs URL: https://docs.google.com/document/d/DOCUMENT_ID/edit â€” you can paste the full Document URL, or just the DOCUMENT_ID into Document ID","Read only extracts plain text â€” there is no table/list structure in the output, and choosing Markdown does not convert formatting","Write deletes ALL existing content before inserting the new text â€” use Append to add without removing what is already there","Create makes a brand-new document and returns documentUrl to share it","Always connect a Google account first via Connections","For read/write/append, ensure the connected Google account has access to the target document"],"docsHref":"/docs/nodes/google_doc","why":"Stores all action items as one document block, avoiding the forbidden per-item fan-out pattern."}}},{"id":"slack_meeting_recap","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Meeting Recap","category":"output","config":{"channel":"#team-updates","message":"{{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Shares the meeting summary and action block with the team in one message."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_2_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_3_js_parse_agent_google_doc_meeting_notes","source":"js_parse_agent","target":"google_doc_meeting_notes"},{"id":"e_4_google_doc_meeting_notes_slack_meeting_recap","source":"google_doc_meeting_notes","target":"slack_meeting_recap"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 20,
    tags                 = ARRAY[$tpl$meetings$tpl$,$tpl$google-docs$tpl$,$tpl$slack$tpl$,$tpl$productivity$tpl$,$tpl$ai-agent$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Meeting Notes to Action Items (NEW)
