) VALUES (
  $tpl$91000000-0000-4000-8000-000000000011$tpl$, $tpl$Meeting Notes to Action Items$tpl$, $tpl$Turn meeting notes into owners and action items, store the summary, and post the task list to the team.$tpl$, $tpl$Sales, Support & Internal Operations$tpl$,
  $tpl$[{"id":"form_meeting_notes","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Meeting Notes Form","category":"triggers","config":{"fields":[{"key":"meetingTitle","type":"text","label":"Meeting Title","required":true},{"key":"notes","type":"textarea","label":"Notes","required":true},{"key":"teamChannel","type":"text","label":"Team Slack Channel","required":false}],"formTitle":"Meeting Notes","submitButtonText":"Create Actions"},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Gives the team a simple way to turn raw notes into follow-up work."}}},{"id":"ai_extract_actions","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Extract Action Items","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Extract action items from these meeting notes: {{input.notes}}. Return ONLY JSON: {\"summary\":\"short summary\",\"actionsText\":\"numbered action list with owner and due date when present\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Finds action items and owners in unstructured notes."}}},{"id":"js_parse_actions","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Action Items","category":"data","config":{"code":"let parsed = {};\ntry { const text = input.response || \"{}\"; const m = text.match(/\\{[\\s\\S]*\\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch (e) { parsed = {}; }\nreturn { ...input, summary: parsed.summary || \"\", actionsText: parsed.actionsText || \"No action items found.\", channel: input.teamChannel || \"#team-updates\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Formats the AI result for storage and Slack posting."}}},{"id":"postgres_save_meeting","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Database","type":"postgresql","label":"Save Meeting Summary","category":"data","config":{"query":"INSERT INTO meeting_summaries (title, summary, actions, created_at) VALUES ('{{input.meetingTitle}}', '{{input.summary}}', '{{input.actionsText}}', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Keeps a searchable record of meeting decisions and tasks."}}},{"id":"slack_post_actions","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Actions to Team","category":"output","config":{"channel":"{{input.channel}}","message":"*{{input.meetingTitle}} actions*\n{{input.actionsText}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the follow-up list where the team already coordinates."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_meeting_notes_ai_extract_actions","source":"form_meeting_notes","target":"ai_extract_actions"},{"id":"e_2_ai_extract_actions_js_parse_actions","source":"ai_extract_actions","target":"js_parse_actions"},{"id":"e_3_js_parse_actions_postgres_save_meeting","source":"js_parse_actions","target":"postgres_save_meeting"},{"id":"e_4_postgres_save_meeting_slack_post_actions","source":"postgres_save_meeting","target":"slack_post_actions"}]$tpl$::jsonb, $tpl$Beginner$tpl$,
  15, ARRAY[$tpl$operations$tpl$,$tpl$meetings$tpl$,$tpl$actions$tpl$,$tpl$ai$tpl$,$tpl$slack$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
