-- Missed Lab Result Chaser (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$92000000-0000-4000-8000-000000000044$tpl$, $tpl$Missed Lab Result Chaser$tpl$, $tpl$Poll one pending lab result, send a patient chaser, alert the care team, and stamp the record.$tpl$, $tpl$Healthcare & Clinics$tpl$,
  $tpl$[{"id":"schedule_poll","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Poll One Due Record","category":"triggers","config":{"cron":"*/20 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs on a timer and drains one matching record per run because the current runtime does not fan out over multiple rows."}}},{"id":"airtable_read_one","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One Work Item","category":"data","config":{"baseId":"","tableId":"LabResults","operation":"read","filterByFormula":"AND({Status}='Pending', {ChasedAt}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Selects a single unprocessed row and excludes rows already marked by this workflow."}}},{"id":"js_prepare_record","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Prepare Work Item","category":"data","config":{"code":"const rec = (input.records || [])[0];\nconst fields = rec?.fields || {};\nreturn { ...input, recordId: rec?.id || \"\", hasWork: Boolean(rec), ...fields, name: fields.Name || fields.Patient || fields.Client || fields.Vendor || \"record\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Lifts the Airtable record fields and record ID to the top level for downstream nodes."}}},{"id":"if_has_work","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Found Work?","category":"logic","config":{"conditions":[{"field":"$json.hasWork","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Keeps empty polls quiet instead of sending blank messages or wasting AI calls."}}},{"id":"gmail_notify","type":"custom","position":{"x":1380,"y":205},"data":{"icon":"Mail","type":"google_gmail","label":"Send Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.PatientEmail}}","subject":"Lab result follow-up","body":"We are following up on your pending lab result: {{input.TestName}}."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the person responsible the reminder or digest for this one selected record."}}},{"id":"slack_notify","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Team Alert","category":"output","config":{"channel":"#care-team","message":"Pending lab result chased for {{input.Patient}}."},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Posts the same event to the operating channel so the team can see the queue moving."}}},{"id":"airtable_mark_done","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Processed","category":"data","config":{"baseId":"","tableId":"LabResults","operation":"update","recordId":"{{input.recordId}}","fields":{"ChasedAt":"Sent"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Writes the processed marker that makes the scheduled poll idempotent across runs."}}},{"id":"log_no_work","type":"custom","position":{"x":1380,"y":395},"data":{"icon":"Box","type":"log_output","label":"No Work Found","category":"utility","config":{"level":"info","message":"Missed Lab Result Chaser: no matching record this run."},"notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"Leaves a quiet execution trace when there is nothing to process."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_poll_airtable_read_one","source":"schedule_poll","target":"airtable_read_one"},{"id":"e_2_airtable_read_one_js_prepare_record","source":"airtable_read_one","target":"js_prepare_record"},{"id":"e_3_js_prepare_record_if_has_work","source":"js_prepare_record","target":"if_has_work"},{"id":"e_4_if_has_work_gmail_notify","source":"if_has_work","target":"gmail_notify","sourceHandle":"true"},{"id":"e_5_if_has_work_log_no_work","source":"if_has_work","target":"log_no_work","sourceHandle":"false"},{"id":"e_6_gmail_notify_slack_notify","source":"gmail_notify","target":"slack_notify"},{"id":"e_7_slack_notify_airtable_mark_done","source":"slack_notify","target":"airtable_mark_done"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$labs$tpl$,$tpl$follow-up$tpl$,$tpl$clinic$tpl$,$tpl$airtable$tpl$,$tpl$gmail$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$Missed Lab Result Chaser$tpl$,
    description          = $tpl$Poll one pending lab result, send a patient chaser, alert the care team, and stamp the record.$tpl$,
    category             = $tpl$Healthcare & Clinics$tpl$,
    nodes                = $tpl$[{"id":"schedule_poll","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Poll One Due Record","category":"triggers","config":{"cron":"*/20 * * * *","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs on a timer and drains one matching record per run because the current runtime does not fan out over multiple rows."}}},{"id":"airtable_read_one","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read One Work Item","category":"data","config":{"baseId":"","tableId":"LabResults","operation":"read","filterByFormula":"AND({Status}='Pending', {ChasedAt}='')","maxRecords":1},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Selects a single unprocessed row and excludes rows already marked by this workflow."}}},{"id":"js_prepare_record","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Prepare Work Item","category":"data","config":{"code":"const rec = (input.records || [])[0];\nconst fields = rec?.fields || {};\nreturn { ...input, recordId: rec?.id || \"\", hasWork: Boolean(rec), ...fields, name: fields.Name || fields.Patient || fields.Client || fields.Vendor || \"record\" };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Lifts the Airtable record fields and record ID to the top level for downstream nodes."}}},{"id":"if_has_work","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Found Work?","category":"logic","config":{"conditions":[{"field":"$json.hasWork","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Keeps empty polls quiet instead of sending blank messages or wasting AI calls."}}},{"id":"gmail_notify","type":"custom","position":{"x":1380,"y":205},"data":{"icon":"Mail","type":"google_gmail","label":"Send Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.PatientEmail}}","subject":"Lab result follow-up","body":"We are following up on your pending lab result: {{input.TestName}}."},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the person responsible the reminder or digest for this one selected record."}}},{"id":"slack_notify","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Team Alert","category":"output","config":{"channel":"#care-team","message":"Pending lab result chased for {{input.Patient}}."},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Posts the same event to the operating channel so the team can see the queue moving."}}},{"id":"airtable_mark_done","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Mark Processed","category":"data","config":{"baseId":"","tableId":"LabResults","operation":"update","recordId":"{{input.recordId}}","fields":{"ChasedAt":"Sent"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Writes the processed marker that makes the scheduled poll idempotent across runs."}}},{"id":"log_no_work","type":"custom","position":{"x":1380,"y":395},"data":{"icon":"Box","type":"log_output","label":"No Work Found","category":"utility","config":{"level":"info","message":"Missed Lab Result Chaser: no matching record this run."},"notes":{"family":"Utility","what":"Writes a message to your workflow's log for debugging or auditing","overview":"Log data for debugging and monitoring. View logs in the execution history. This is a terminal node â€” it cannot connect to further downstream nodes.","tips":["Use different levels for filtering","This node is terminal â€” it does not forward data to further nodes","Check execution history for logs"],"docsHref":"/docs/nodes/log_output","why":"Leaves a quiet execution trace when there is nothing to process."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_schedule_poll_airtable_read_one","source":"schedule_poll","target":"airtable_read_one"},{"id":"e_2_airtable_read_one_js_prepare_record","source":"airtable_read_one","target":"js_prepare_record"},{"id":"e_3_js_prepare_record_if_has_work","source":"js_prepare_record","target":"if_has_work"},{"id":"e_4_if_has_work_gmail_notify","source":"if_has_work","target":"gmail_notify","sourceHandle":"true"},{"id":"e_5_if_has_work_log_no_work","source":"if_has_work","target":"log_no_work","sourceHandle":"false"},{"id":"e_6_gmail_notify_slack_notify","source":"gmail_notify","target":"slack_notify"},{"id":"e_7_slack_notify_airtable_mark_done","source":"slack_notify","target":"airtable_mark_done"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 20,
    tags                 = ARRAY[$tpl$labs$tpl$,$tpl$follow-up$tpl$,$tpl$clinic$tpl$,$tpl$airtable$tpl$,$tpl$gmail$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Missing Document Finder
UPDATE templates SET
    name                 = $tpl$Missing Document Finder$tpl$,
    description          = $tpl$Stop chasing clients for 'one more document.' Upload whatever paperwork a client has sent so far, in any order, and this workflow figures out exactly which required documents are still missing and emails the client a specific checklist.$tpl$,
    category             = $tpl$Business Verification & Compliance$tpl$,
    nodes                = $tpl$[{"id":"form_doc_upload","data":{"icon":"FileText","type":"form","label":"Document Upload Form","config":{"fields":[{"key":"clientName","type":"text","label":"Client / Business Name","required":true},{"key":"clientType","type":"select","label":"Client Type","required":true,"options":["Individual","Business"]},{"key":"document","type":"file","label":"Document","required":true},{"key":"contactEmail","type":"email","label":"Contact Email","required":true}],"formTitle":"Upload Your Documents","formDescription":"Upload whatever documents you have — in any order. We will tell you what is still missing.","submitButtonText":"Upload"},"category":"triggers","notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Lets a client upload whatever they have, in any order. The client type chosen here decides which checklist applies."}},"type":"custom","position":{"x":100,"y":300}},{"id":"ai_classify_document","data":{"icon":"Brain","type":"google_gemini","label":"Identify Document Type","config":{"model":"gemini-3.5-flash","prompt":"Look at this uploaded file (name and content provided): {{input.document}}. Identify which document type it most likely is, choosing from: GST Certificate, PAN Card, Bank Statement, Address Proof, Business Registration, Photo ID, Other. Reply with only the document type name."},"category":"ai","notes":{"family":"AI","what":"Uses Google's Gemini AI to generate text, answer questions, or analyze content","overview":"Calls Google Gemini through the LLM adapter and returns response, model, usage, and finishReason. The current executor resolves Gemini credentials from connection/wallet/key-pool/direct config, and it does not preserve incoming fields on success.","tips":[],"docsHref":"/docs/nodes/google_gemini","why":"Identifies what each uploaded file actually is, so clients do not have to label anything correctly."}},"type":"custom","position":{"x":420,"y":300}},{"id":"airtable_log_document","data":{"icon":"Database","type":"airtable","label":"Log Received Document","config":{"baseId":"","fields":{"Client":"{{input.clientName}}","DocumentType":"{{input.response}}"},"tableId":"DocumentsReceived","operation":"create"},"category":"data","notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Records the document against the client, building the running history the check below depends on."}},"type":"custom","position":{"x":740,"y":300}},{"id":"js_check_missing","data":{"icon":"Code","type":"javascript","label":"Compare Against Checklist","config":{"code":"const required = { 'Individual': ['PAN Card','Address Proof','Photo ID'], 'Business': ['GST Certificate','PAN Card','Bank Statement','Business Registration'] };\nconst checklist = required[input.clientType] || required['Business'];\n// Every document logged for this client so far, from the Airtable read above.\nconst received = (input.records || []).map(r => (r.fields && r.fields.DocumentType) || \"\").filter(Boolean);\nconst missing = checklist.filter(doc => !received.includes(doc));\nreturn { ...input, received, missing, isComplete: missing.length === 0 };"},"category":"data","notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Compares the full set received against the required checklist. The two checklists — Individual and Business — are defined here."}},"type":"custom","position":{"x":1380,"y":300}},{"id":"ai_write_missing_message","data":{"icon":"Brain","type":"openai_gpt","label":"Write Missing Docs Message","config":{"model":"gpt-4o-mini","prompt":"Write a short, friendly email message to {{input.clientName}} listing exactly which documents are still missing: {{input.missing}}. If nothing is missing, congratulate them that their file is complete. Keep it under 3 sentences.","temperature":0.6},"category":"ai","notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Writes a short, friendly chase message rather than a blunt system list."}},"type":"custom","position":{"x":1700,"y":300}},{"id":"whatsapp_send_missing","data":{"icon":"Mail","type":"google_gmail","label":"Email Missing Docs List","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.contactEmail}}","subject":"Missing documents for {{input.clientName}}","body":"{{input.response}}"},"category":"output","notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Emails the client exactly what is still outstanding, which is what stops the back-and-forth."}},"type":"custom","position":{"x":2020,"y":300}},{"id":"airtable_read_prior_docs","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Database","type":"airtable","label":"Read All Documents Received So Far","category":"data","config":{"baseId":"","tableId":"DocumentsReceived","operation":"read","filterByFormula":"{Client}='{{input.clientName}}'","maxRecords":100},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Reads everything this client has ever sent. Without this the checklist only sees the file just uploaded and reports almost everything as missing."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e1","source":"form_doc_upload","target":"ai_classify_document"},{"id":"e2","source":"ai_classify_document","target":"airtable_log_document"},{"id":"e3","source":"airtable_log_document","target":"airtable_read_prior_docs"},{"id":"e4","source":"js_check_missing","target":"ai_write_missing_message"},{"id":"e5","source":"ai_write_missing_message","target":"whatsapp_send_missing"},{"id":"e_airtable_read_prior_docs_js_check_missing","source":"airtable_read_prior_docs","target":"js_check_missing"}]$tpl$::jsonb,
    difficulty           = $tpl$Beginner$tpl$,
    estimated_setup_time = 18,
    tags                 = ARRAY[$tpl$verification$tpl$,$tpl$onboarding$tpl$,$tpl$documents$tpl$,$tpl$ai$tpl$,$tpl$email$tpl$,$tpl$airtable$tpl$]::text[],
    version              = 2,
    updated_at           = now()
WHERE id = $tpl$58703e5c-2ec9-437f-9b05-264a017e5ce8$tpl$;

-- Multi-Channel Customer Support Agent (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000001$tpl$, $tpl$Multi-Channel Customer Support Agent$tpl$, $tpl$Receive support payloads from any channel, ground the answer in a verified ticket log, reply through HubSpot, and escalate uncertain cases to Slack.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/multi-channel-customer-support-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.customerId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_ticket_history","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Database","type":"airtable","label":"Read Ticket History","category":"data","config":{"baseId":"","tableId":"SupportTickets","operation":"read","filterByFormula":"SEARCH('{{input.customerEmail}}', {Email})","maxRecords":10},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Replaces the blocked Zendesk lookup with a verified ticket-history table the agent can consult before answering."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are a support agent. Use the ticket-history tool result before drafting a reply. If the customer is angry, the issue is unsafe, or confidence is low, set needsHuman true. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"if_needs_human","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Human?","category":"logic","config":{"conditions":[{"field":"$json.needsHuman","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Separates cases that should not be answered automatically from safe support replies."}}},{"id":"slack_escalate","type":"custom","position":{"x":1700,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Escalate to Support","category":"output","config":{"channel":"#support-escalations","message":"Support escalation for {{input.customerEmail}}: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes low-confidence or angry customer issues to a human support queue."}}},{"id":"hubspot_log_reply","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Zap","type":"hubspot","label":"Log Support Reply in HubSpot","category":"crm","config":{"resource":"contact","operation":"update","id":"{{input.customerId}}","properties":{"last_support_summary":"{{input.summary}}","last_support_reply":"{{input.message}}"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Uses verified HubSpot instead of blocked Zendesk so the response history lands in a CRM record."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_webhook_intake_memory_context","source":"webhook_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_webhook_intake_tool_ticket_history","source":"webhook_intake","target":"tool_ticket_history"},{"id":"e_4_tool_ticket_history_ai_agent","source":"tool_ticket_history","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_if_needs_human","source":"js_parse_agent","target":"if_needs_human"},{"id":"e_8_if_needs_human_slack_escalate","source":"if_needs_human","target":"slack_escalate","sourceHandle":"true"},{"id":"e_9_if_needs_human_hubspot_log_reply","source":"if_needs_human","target":"hubspot_log_reply","sourceHandle":"false"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$support$tpl$,$tpl$ai-agent$tpl$,$tpl$hubspot$tpl$,$tpl$slack$tpl$,$tpl$webhook$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$Multi-Channel Customer Support Agent$tpl$,
    description          = $tpl$Receive support payloads from any channel, ground the answer in a verified ticket log, reply through HubSpot, and escalate uncertain cases to Slack.$tpl$,
    category             = $tpl$AI Agent$tpl$,
    nodes                = $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/multi-channel-customer-support-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.customerId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_ticket_history","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Database","type":"airtable","label":"Read Ticket History","category":"data","config":{"baseId":"","tableId":"SupportTickets","operation":"read","filterByFormula":"SEARCH('{{input.customerEmail}}', {Email})","maxRecords":10},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Replaces the blocked Zendesk lookup with a verified ticket-history table the agent can consult before answering."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are a support agent. Use the ticket-history tool result before drafting a reply. If the customer is angry, the issue is unsafe, or confidence is low, set needsHuman true. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"if_needs_human","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Human?","category":"logic","config":{"conditions":[{"field":"$json.needsHuman","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Separates cases that should not be answered automatically from safe support replies."}}},{"id":"slack_escalate","type":"custom","position":{"x":1700,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Escalate to Support","category":"output","config":{"channel":"#support-escalations","message":"Support escalation for {{input.customerEmail}}: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Routes low-confidence or angry customer issues to a human support queue."}}},{"id":"hubspot_log_reply","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Zap","type":"hubspot","label":"Log Support Reply in HubSpot","category":"crm","config":{"resource":"contact","operation":"update","id":"{{input.customerId}}","properties":{"last_support_summary":"{{input.summary}}","last_support_reply":"{{input.message}}"}},"notes":{"family":"CRM","what":"Create, update, or find contacts, deals, and companies in HubSpot CRM","overview":"Connects to HubSpot CRM to get, list, create, update, delete, search, or bulk-create contacts, companies, deals, and tickets. Only Access Token is vault-backed - Api Key and Credential Id are legacy/unused. Perfect for automating sales, marketing, and support workflows.","tips":[],"docsHref":"/docs/nodes/hubspot","why":"Uses verified HubSpot instead of blocked Zendesk so the response history lands in a CRM record."}}}]$tpl$::jsonb,
