-- Personal Daily Digest Assistant (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000007$tpl$, $tpl$Personal Daily Digest Assistant$tpl$, $tpl$Build a weekday morning digest from unread Gmail and calendar context, then post it to Slack.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"schedule_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Scheduled Run","category":"triggers","config":{"cron":"0 7 * * 1-5","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs the agent on a predictable schedule so the workflow does not depend on an unsupported vendor trigger."}}},{"id":"tool_unread_gmail","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Mail","type":"google_gmail","label":"Read Unread Gmail","category":"output","config":{"operation":"search","query":"is:unread newer_than:1d"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Supplies unread-mail context for the morning digest."}}},{"id":"tool_today_calendar","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Calendar","type":"google_calendar","label":"Read Today Calendar","category":"data","config":{"resource":"event","operation":"list","calendarId":"primary","maxResults":10},"notes":{"family":"Data","what":"Read, create, update, or delete events in your Google Calendar","overview":"Create, list, update, or delete Google Calendar events. Manage your calendar programmatically. Runtime also supports get, quickAdd, and move for events, plus non-event resources, when set directly in workflow JSON.","tips":["Use \"primary\" for main calendar","Times must be ISO 8601 format (UTC) â€” Start Time/End Time are converted automatically","The new/updated event ID is returned as id, not eventId","List returns events in the Time Min/Time Max window, with no date filtering by default"],"docsHref":"/docs/nodes/google_calendar","why":"Supplies calendar context for the morning schedule section."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Summarize today in a concise morning briefing: three email highlights and the day schedule. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"none"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"slack_daily_digest","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Daily Digest","category":"output","config":{"channel":"#daily-digest","message":"{{input.message}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Publishes the daily briefing to the personal digest channel."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_schedule_intake_tool_unread_gmail","source":"schedule_intake","target":"tool_unread_gmail"},{"id":"e_2_tool_unread_gmail_ai_agent","source":"tool_unread_gmail","target":"ai_agent","targetHandle":"tool"},{"id":"e_3_schedule_intake_tool_today_calendar","source":"schedule_intake","target":"tool_today_calendar"},{"id":"e_4_tool_today_calendar_ai_agent","source":"tool_today_calendar","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_schedule_intake_ai_agent","source":"schedule_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_slack_daily_digest","source":"js_parse_agent","target":"slack_daily_digest"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$daily-digest$tpl$,$tpl$gmail$tpl$,$tpl$calendar$tpl$,$tpl$slack$tpl$,$tpl$ai-agent$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
ON CONFLICT (id) DO UPDATE SET
    name                 = $tpl$Personal Daily Digest Assistant$tpl$,
    description          = $tpl$Build a weekday morning digest from unread Gmail and calendar context, then post it to Slack.$tpl$,
    category             = $tpl$AI Agent$tpl$,
    nodes                = $tpl$[{"id":"schedule_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"schedule","label":"Scheduled Run","category":"triggers","config":{"cron":"0 7 * * 1-5","timezone":"Asia/Kolkata"},"notes":{"family":"Triggers","what":"Works like an alarm clock — runs your workflow automatically at a specific time you set each day","overview":"Runs your workflow automatically on a schedule using a simple time picker. Select your time (HH:MM format) and timezone, and the workflow will execute daily at that time. Great for daily reports, periodic checks, or recurring tasks.","tips":["Use 24-hour format (e.g., 09:00 for 9 AM, 14:30 for 2:30 PM)","Select your timezone from the dropdown (IST, UTC, etc.)","Workflow runs daily at the specified time","Test with manual trigger first","Timezone conversion is handled automatically"],"docsHref":"/docs/nodes/schedule","why":"Runs the agent on a predictable schedule so the workflow does not depend on an unsupported vendor trigger."}}},{"id":"tool_unread_gmail","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Mail","type":"google_gmail","label":"Read Unread Gmail","category":"output","config":{"operation":"search","query":"is:unread newer_than:1d"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Supplies unread-mail context for the morning digest."}}},{"id":"tool_today_calendar","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Calendar","type":"google_calendar","label":"Read Today Calendar","category":"data","config":{"resource":"event","operation":"list","calendarId":"primary","maxResults":10},"notes":{"family":"Data","what":"Read, create, update, or delete events in your Google Calendar","overview":"Create, list, update, or delete Google Calendar events. Manage your calendar programmatically. Runtime also supports get, quickAdd, and move for events, plus non-event resources, when set directly in workflow JSON.","tips":["Use \"primary\" for main calendar","Times must be ISO 8601 format (UTC) â€” Start Time/End Time are converted automatically","The new/updated event ID is returned as id, not eventId","List returns events in the Time Min/Time Max window, with no date filtering by default"],"docsHref":"/docs/nodes/google_calendar","why":"Supplies calendar context for the morning schedule section."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Summarize today in a concise morning briefing: three email highlights and the day schedule. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"none"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"slack_daily_digest","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Post Daily Digest","category":"output","config":{"channel":"#daily-digest","message":"{{input.message}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Publishes the daily briefing to the personal digest channel."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_schedule_intake_tool_unread_gmail","source":"schedule_intake","target":"tool_unread_gmail"},{"id":"e_2_tool_unread_gmail_ai_agent","source":"tool_unread_gmail","target":"ai_agent","targetHandle":"tool"},{"id":"e_3_schedule_intake_tool_today_calendar","source":"schedule_intake","target":"tool_today_calendar"},{"id":"e_4_tool_today_calendar_ai_agent","source":"tool_today_calendar","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_schedule_intake_ai_agent","source":"schedule_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_slack_daily_digest","source":"js_parse_agent","target":"slack_daily_digest"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 20,
    tags                 = ARRAY[$tpl$daily-digest$tpl$,$tpl$gmail$tpl$,$tpl$calendar$tpl$,$tpl$slack$tpl$,$tpl$ai-agent$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Policy Page Presence Checker (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$92000000-0000-4000-8000-000000000003$tpl$, $tpl$Policy Page Presence Checker$tpl$, $tpl$Fetch a submitted homepage, check for required policy-page signals, email the fix list, and log the result.$tpl$, $tpl$Business Verification & Compliance$tpl$,
  $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Intake Details","category":"triggers","config":{"formTitle":"Policy Page Presence Checker","fields":[{"key":"businessName","label":"Business Name","type":"text","required":true},{"key":"email","label":"Email","type":"email","required":true},{"key":"homepageUrl","label":"Homepage Url","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request so the workflow handles a single record per run."}}},{"id":"http_enrich","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Globe","type":"http_request","label":"Fetch External Context","category":"http_api","config":{"url":"{{input.homepageUrl}}","method":"GET","timeout":10000},"notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Fetches static API or website context needed for the assessment; credentials stay in the connected service, not in the template."}}},{"id":"ai_classify","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Classify and Draft","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Check this static homepage response for privacy policy, terms, refund, contact, and business identity signals: {{input.body}}. Return ONLY JSON: {\"route\":\"routine|review\",\"summary\":\"missing pages\",\"message\":\"plain-language fix list\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Turns the incoming business context into structured fields the routing and message steps can trust."}}},{"id":"js_parse_ai","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse AI JSON","category":"data","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || \"{}\";\n  const match = String(text).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nreturn { ...input, ...parsed };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Parses the AI JSON into real workflow fields before any branch reads those fields."}}},{"id":"if_route","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Attention?","category":"logic","config":{"conditions":[{"field":"$json.route","operator":"equals","value":"review"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Splits high-attention work from routine handling using one explicit comparison."}}},{"id":"slack_review","type":"custom","position":{"x":1700,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Notify Team","category":"output","config":{"channel":"#compliance","message":"Policy Page Presence Checker: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the exception in front of the team that can act on it."}}},{"id":"gmail_routine","type":"custom","position":{"x":1700,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Send Routine Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.email}}","subject":"Website policy page check","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the routine response or acknowledgement without requiring a manual handoff."}}},{"id":"store_result","type":"custom","position":{"x":2020,"y":300},"data":{"icon":"Database","type":"airtable","label":"Log Result","category":"data","config":{"baseId":"","tableId":"PolicyChecks","operation":"create","fields":{"Name":"{{input.name}}","Email":"{{input.email}}","Summary":"{{input.summary}}","Route":"{{input.route}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Logs the assessment so the team has a durable queue outside the execution log."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_intake_http_enrich","source":"form_intake","target":"http_enrich"},{"id":"e_2_http_enrich_ai_classify","source":"http_enrich","target":"ai_classify"},{"id":"e_3_ai_classify_js_parse_ai","source":"ai_classify","target":"js_parse_ai"},{"id":"e_4_js_parse_ai_if_route","source":"js_parse_ai","target":"if_route"},{"id":"e_5_if_route_slack_review","source":"if_route","target":"slack_review","sourceHandle":"true"},{"id":"e_6_if_route_gmail_routine","source":"if_route","target":"gmail_routine","sourceHandle":"false"},{"id":"e_7_slack_review_store_result","source":"slack_review","target":"store_result"},{"id":"e_8_gmail_routine_store_result","source":"gmail_routine","target":"store_result"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  18, ARRAY[$tpl$website$tpl$,$tpl$policy$tpl$,$tpl$verification$tpl$,$tpl$gmail$tpl$,$tpl$airtable$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
