) VALUES (
  $tpl$93000000-0000-4000-8000-000000000009$tpl$, $tpl$RAG Document Q&A Agent$tpl$, $tpl$Answer document questions from a Pinecone knowledge base; Drive ingestion is handled by a scheduled poll variant instead of an unsupported Drive trigger.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"chat_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"chat_trigger","label":"Receive Chat Message","category":"triggers","config":{},"notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Starts the agent from one chat message and preserves the session data for replies."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.sessionId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_pinecone_query","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Database","type":"pinecone","label":"Query Pinecone Knowledge Base","category":"data","config":{"operation":"query","index":"REPLACE_WITH_PINECONE_INDEX","vector":"{{input.embedding}}","topK":5},"notes":{"family":"Data","what":"Stores or searches vector embeddings in Pinecone — used for AI-powered semantic search","overview":"Store, query, and delete embedding vectors in a Pinecone index. Query returns matches with metadata, upsert returns upsertedCount, and delete returns a successful empty match list.","tips":["Use the full index host URL for serverless Pinecone indexes.","Vector must match the index dimension exactly.","Use stable IDs for upsert so re-indexing updates the same vector instead of creating duplicates.","Store API keys in Connections or a credential vault.","Use namespaces to separate tenants, environments, or source systems."],"docsHref":"/docs/nodes/pinecone","why":"Uses Pinecone as the verified vector lookup tool for the Q&A side of the RAG pattern."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Answer only from the Pinecone knowledge-base context. Cite the source chunk when possible, and say you do not know if nothing relevant is present. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"chat_rag_answer","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Send","type":"chat_send","label":"Reply with Cited Answer","category":"output","config":{"message":"{{input.message}}"},"notes":{"family":"Database","what":"Sends a reply in a chat conversation — works with a chat trigger to create a bot","overview":"","tips":[],"docsHref":null,"why":"Returns the grounded RAG answer in the active chat session."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_chat_intake_memory_context","source":"chat_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_chat_intake_tool_pinecone_query","source":"chat_intake","target":"tool_pinecone_query"},{"id":"e_4_tool_pinecone_query_ai_agent","source":"tool_pinecone_query","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_chat_intake_ai_agent","source":"chat_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_chat_rag_answer","source":"js_parse_agent","target":"chat_rag_answer"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$rag$tpl$,$tpl$pinecone$tpl$,$tpl$chat$tpl$,$tpl$knowledge-base$tpl$,$tpl$ai-agent$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
