) VALUES (
  $tpl$92000000-0000-4000-8000-000000000028$tpl$, $tpl$Refund Request Triage$tpl$, $tpl$Classify one refund request, distinguish routine from approval-needed cases, acknowledge the customer, and log the queue item.$tpl$, $tpl$Finance, Accounting & Insurance$tpl$,
  $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Intake Details","category":"triggers","config":{"formTitle":"Refund Request Triage","fields":[{"key":"customerEmail","label":"Customer Email","type":"email","required":true},{"key":"orderId","label":"Order Id","type":"text","required":true},{"key":"amount","label":"Amount","type":"text","required":true},{"key":"reason","label":"Reason","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request so the workflow handles a single record per run."}}},{"id":"ai_classify","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Classify and Draft","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Triage this refund request. Return ONLY JSON: {\"requiresApproval\":true|false,\"summary\":\"legitimacy and reason\",\"message\":\"customer acknowledgement\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Turns the incoming business context into structured fields the routing and message steps can trust."}}},{"id":"js_parse_ai","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse AI JSON","category":"data","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || \"{}\";\n  const match = String(text).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nreturn { ...input, ...parsed };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Parses the AI JSON into real workflow fields before any branch reads those fields."}}},{"id":"if_route","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Attention?","category":"logic","config":{"conditions":[{"field":"$json.requiresApproval","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Splits high-attention work from routine handling using one explicit comparison."}}},{"id":"slack_review","type":"custom","position":{"x":1380,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Notify Team","category":"output","config":{"channel":"#finance","message":"Refund Request Triage: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the exception in front of the team that can act on it."}}},{"id":"gmail_routine","type":"custom","position":{"x":1380,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Send Routine Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.customerEmail}}","subject":"Refund request received","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the routine response or acknowledgement without requiring a manual handoff."}}},{"id":"store_result","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Database","type":"postgresql","label":"Store Result","category":"data","config":{"query":"INSERT INTO template_events (template_name, summary, route, created_at) VALUES ('Refund Request Triage', '{{input.summary}}', '{{input.route}}', now())"},"notes":{"family":"Data","what":"Connects to a PostgreSQL database to run queries or insert data","overview":"Run PostgreSQL executeQuery, insert, update, or delete through the real database executor. The visual panel now uses runtime operation values and Parameters maps to the executor parameter array.","tips":["Use executeQuery for raw SQL with $1, $2 placeholders and Parameters as a JSON array.","Insert returns inserted/count; update and delete return rows/rowsAffected because PostgreSQL uses RETURNING *.","The backend schema still lists connectionString, but the executor validates host, username, password, database, port, and ssl.","Update and delete require Where; the executor refuses missing where clauses.","Store database passwords in Connections rather than ordinary workflow fields."],"docsHref":"/docs/nodes/postgresql","why":"Stores the decision in PostgreSQL for audit and follow-up."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_form_intake_ai_classify","source":"form_intake","target":"ai_classify"},{"id":"e_2_ai_classify_js_parse_ai","source":"ai_classify","target":"js_parse_ai"},{"id":"e_3_js_parse_ai_if_route","source":"js_parse_ai","target":"if_route"},{"id":"e_4_if_route_slack_review","source":"if_route","target":"slack_review","sourceHandle":"true"},{"id":"e_5_if_route_gmail_routine","source":"if_route","target":"gmail_routine","sourceHandle":"false"},{"id":"e_6_slack_review_store_result","source":"slack_review","target":"store_result"},{"id":"e_7_gmail_routine_store_result","source":"gmail_routine","target":"store_result"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
