-- Resume Screening Agent (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000023$tpl$, $tpl$Resume Screening Agent$tpl$, $tpl$Receive resume payloads by webhook, score fit against role requirements, log candidates, and alert recruiters for strong matches.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/resume-screening-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"tool_role_requirements","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Table","type":"google_sheets","label":"Read Role Requirements","category":"data","config":{"operation":"read","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Role Requirements!A:Z"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Replaces Gmail Trigger with webhook intake while preserving role-requirement context."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gpt-4o","temperature":0.1,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"Screen this resume against the role requirements. Return score, rationale, standout skills, and strongMatch true when score is at least 80. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"none","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"sheets_log_candidate","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Table","type":"google_sheets","label":"Append Candidate Row","category":"data","config":{"operation":"append","spreadsheetId":"REPLACE_WITH_YOUR_GOOGLE_SHEET_ID","range":"Candidates!A:F","values":"{{input.summary}}"},"notes":{"family":"Data","what":"Read rows from a Google Sheet or write new data into one — like Excel, but automated","overview":"Read, write, append, or update data in Google Sheets. Connect your spreadsheets to workflows for data extraction, logging, and automation.","tips":["Get Spreadsheet ID from URL: /d/SPREADSHEET_ID/edit","Leave range empty to read all used cells","Use key-value or text Output Format for easier AI processing","Allow Write Access has no runtime effect â€” write/append/update run regardless of this checkbox","Data is checked before Values when both are filled","Authenticate with Google account first"],"docsHref":"/docs/nodes/google_sheets","why":"Logs every screened candidate in the recruiting tracker."}}},{"id":"if_strong_candidate","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Strong Match?","category":"logic","config":{"conditions":[{"field":"$json.strongMatch","operator":"equals","value":true}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choos