    edges                = $tpl$[{"id":"e_1_schedule_intake_tool_review_feed","source":"schedule_intake","target":"tool_review_feed"},{"id":"e_2_tool_review_feed_ai_agent","source":"tool_review_feed","target":"ai_agent","targetHandle":"tool"},{"id":"e_3_schedule_intake_ai_agent","source":"schedule_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_4_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_5_js_parse_agent_sentiment_score_summary","source":"js_parse_agent","target":"sentiment_score_summary"},{"id":"e_6_sentiment_score_summary_if_negative_spike","source":"sentiment_score_summary","target":"if_negative_spike"},{"id":"e_7_if_negative_spike_slack_brand_watch","source":"if_negative_spike","target":"slack_brand_watch","sourceHandle":"true"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
