-- Shopify Email Order Support Agent (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000002$tpl$, $tpl$Shopify Email Order Support Agent$tpl$, $tpl$Answer order-status requests from a webhook-fed support channel using Shopify lookup context and verified Gmail notifications.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/shopify-email-order-support-agent","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.customerEmail}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_shopify_order","type":"custom","position":{"x":420,"y":395},"data":{"icon":"ShoppingBag","type":"shopify","label":"Look Up Shopify Order","category":"ecommerce","config":{"resource":"order","operation":"get","id":"{{input.orderId}}"},"notes":{"family":"Ecommerce","what":"Reads or manages orders, products, and customers in your Shopify store","overview":"Shopify Admin API operations. Runtime expects resource plus generic operation values get/list/create/update/delete; current product/order/customer operation aliases are not translated.","tips":[],"docsHref":"/docs/nodes/shopify","why":"Keeps the source template Shopify lookup, but only as verified order context for the agent."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are an order-status assistant for a Shopify store. Use the Shopify order context, give status and tracking if available, and never guess. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"gmail_order_reply","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Mail","type":"google_gmail","label":"Email Order Status","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.customerEmail}}","subject":"Order status update","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Replaces the blocked WhatsApp reply with verified Gmail customer notification."}}},{"id":"slack_order_followup","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Hash","type":"slack_message","label":"Notify Support on Missing Order","category":"output","config":{"channel":"#support","message":"Order lookup needs human follow-up: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Gives support a handoff when Shopify context is missing or ambiguous."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_webhook_intake_memory_context","source":"webhook_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_webhook_intake_tool_shopify_order","source":"webhook_intake","target":"tool_shopify_order"},{"id":"e_4_tool_shopify_order_ai_agent","source":"tool_shopify_order","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_pa