    nodes                = $tpl$[{"id":"form_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"form","label":"Collect Intake Details","category":"triggers","config":{"formTitle":"Tax/GST ID Format Validator","fields":[{"key":"clientName","label":"Client Name","type":"text","required":true},{"key":"email","label":"Email","type":"email","required":true},{"key":"country","label":"Country","type":"text","required":true},{"key":"taxId","label":"Tax Id","type":"text","required":true}],"submitButtonText":"Submit","successMessage":"Received."},"notes":{"family":"Triggers","what":"Starts your workflow when someone fills out and submits a web form you built","overview":"Build a public CtrlChecks form and start the workflow when someone submits structured answers, files, or intake details.","tips":["Use friendly labels for submitters and stable internal names for workflow mapping.","Map answers with {{$json.customer_email}} or {{$json.data.customer_email}} after checking a test execution.","Use select or radio options for values that drive routing, approvals, reporting, or branch conditions.","Turn CAPTCHA on for public forms that can create tickets, leads, or notifications.","Require authentication only for internal or sensitive forms.","Changing an internal name after downstream nodes are mapped requires updating those mappings too."],"docsHref":"/docs/nodes/form","why":"Collects one complete request so the workflow handles a single record per run."}}},{"id":"ai_classify","type":"custom","position":{"x":420,"y":300},"data":{"icon":"Box","type":"openai_gpt","label":"Classify and Draft","category":"ai","config":{"model":"gpt-4o-mini","prompt":"Validate the format of this tax identifier for {{input.country}}: {{input.taxId}}. Return ONLY JSON: {\"valid\":true|false,\"summary\":\"validation result\",\"message\":\"clear explanation\"}.","temperature":0.2},"notes":{"family":"AI","what":"Sends your prompt to OpenAI's ChatGPT and gets back an AI-written response","overview":"Calls OpenAI through the legacy LLM adapter. Prompt is the main input; Messages is only a fallback when Prompt is blank. Temperature and Memory are visible legacy fields ignored by the current executor.","tips":[],"docsHref":"/docs/nodes/openai_gpt","why":"Turns the incoming business context into structured fields the routing and message steps can trust."}}},{"id":"js_parse_ai","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse AI JSON","category":"data","config":{"code":"let parsed = {};\ntry {\n  const text = input.response || input.text || \"{}\";\n  const match = String(text).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nreturn { ...input, ...parsed };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Parses the AI JSON into real workflow fields before any branch reads those fields."}}},{"id":"if_route","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"GitBranch","type":"if_else","label":"Needs Attention?","category":"logic","config":{"conditions":[{"field":"$json.valid","operator":"equals","value":"review"}],"combineOperation":"AND"},"notes":{"family":"Logic","what":"Makes a yes/no decision: if something is true, go one way; otherwise go another","overview":"Makes a yes/no decision from previous-step data and routes matching work through TRUE and non-matching work through FALSE.","tips":["Use the builder for normal setup; use JSON mode only when pasting prepared condition objects.","Choose AND when every row must match; choose OR when any row can match.","Use equals for statuses and categories, greater-than operators for numeric thresholds, and contains for text or lists.","Connect both TRUE and FALSE outputs so no business case silently disappears."],"docsHref":"/docs/nodes/if_else","why":"Splits high-attention work from routine handling using one explicit comparison."}}},{"id":"slack_review","type":"custom","position":{"x":1380,"y":205},"data":{"icon":"Hash","type":"slack_message","label":"Notify Team","category":"output","config":{"channel":"#compliance","message":"Tax/GST ID Format Validator: {{input.summary}}"},"notes":{"family":"Communication","what":"Sends messages using a Slack app or bot connection","overview":"Send Slack bot messages to channels, direct messages, or existing threads through a saved Slack OAuth2 connection. Use it for workplace alerts, support replies, incident updates, approvals, report summaries, and deployment notifications.","tips":["Select a Slack OAuth2 connection; do not paste bot tokens into message fields","The Slack app needs chat:write, and the bot must be invited before it can post in private channels","Use {{$json.channelId}} and {{$json.threadTs}} from Slack Trigger to reply in the same conversation","Keep Message filled as readable fallback text even when Blocks contains a rich Block Kit layout","Connect downstream service accounts separately; Slack OAuth2 only authorizes the Slack send"],"docsHref":"/docs/nodes/slack_message","why":"Puts the exception in front of the team that can act on it."}}},{"id":"gmail_routine","type":"custom","position":{"x":1380,"y":395},"data":{"icon":"Mail","type":"google_gmail","label":"Send Routine Email","category":"output","config":{"operation":"send","recipientSource":"manual_entry","recipientEmails":"{{input.email}}","subject":"Tax ID validation result","body":"{{input.message}}"},"notes":{"family":"Communication","what":"Send emails from your Gmail account or read and search messages in your inbox","overview":"Send, list, get, or search Gmail messages. Send recipients can be typed manually or extracted from upstream/fallback Google Sheets rows.","tips":["Connect Google OAuth in Connections; do not paste tokens into workflow fields","Gmail search syntax: from:, subject:, is:unread, has:attachment","List/Search only return {id, threadId} per message â€” use a Get step with that id for full content","Body is plain text only","Get returns Gmail's raw API message; the body text is base64url-encoded inside message.payload.body.data","Use search to filter messages before getting details"],"docsHref":"/docs/nodes/google_gmail","why":"Sends the routine response or acknowledgement without requiring a manual handoff."}}},{"id":"store_result","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Database","type":"airtable","label":"Log Result","category":"data","config":{"baseId":"","tableId":"TaxIdChecks","operation":"create","fields":{"Name":"{{input.name}}","Email":"{{input.email}}","Summary":"{{input.summary}}","Route":"{{input.route}}"}},"notes":{"family":"Data","what":"Reads rows from an Airtable base or adds new records — like a smarter spreadsheet","overview":"List, get, create, update, upsert, and delete Airtable records. The resource dropdown is visual only; runtime implements record operations, not table-management APIs.","tips":["Use a Personal Access Token with data.records scopes or a saved Airtable connection","Base ID plus table/tableId are required for every operation","Create/update/upsert return records/count","Upsert also returns created and updated counts","Delete returns deletedRecords/count, not top-level deleted:true"],"docsHref":"/docs/nodes/airtable","why":"Logs the assessment so the team has a durable queue outside the execution log."}}}]$tpl$::jsonb,
    edges                = $tpl$[{"id":"e_1_form_intake_ai_classify","source":"form_intake","target":"ai_classify"},{"id":"e_2_ai_classify_js_parse_ai","source":"ai_classify","target":"js_parse_ai"},{"id":"e_3_js_parse_ai_if_route","source":"js_parse_ai","target":"if_route"},{"id":"e_4_if_route_slack_review","source":"if_route","target":"slack_review","sourceHandle":"true"},{"id":"e_5_if_route_gmail_routine","source":"if_route","target":"gmail_routine","sourceHandle":"false"},{"id":"e_6_slack_review_store_result","source":"slack_review","target":"store_result"},{"id":"e_7_gmail_routine_store_result","source":"gmail_routine","target":"store_result"}]$tpl$::jsonb,
    difficulty           = $tpl$Intermediate$tpl$,
    estimated_setup_time = 18,
    tags                 = ARRAY[$tpl$tax$tpl$,$tpl$gst$tpl$,$tpl$validation$tpl$,$tpl$compliance$tpl$,$tpl$gmail$tpl$]::text[],
    version              = 2,
    updated_at           = now();

-- Telegram Long-Term Memory Assistant (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000004$tpl$, $tpl$Telegram Long-Term Memory Assistant$tpl$, $tpl$Run a personal Telegram assistant that remembers context and appends remembered notes to a Google Doc.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"webhook_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"webhook","label":"Receive Event Payload","category":"triggers","config":{"path":"/telegram-long-term-memory-assistant","httpMethod":"POST","responseMode":"onReceived"},"notes":{"family":"Triggers","what":"Starts your workflow the moment another app sends it data — like a doorbell for your automation","overview":"Starts a workflow when an external app, website form, payment system, or internal service sends data to the generated CtrlChecks webhook URL. Captures the request body, headers, query values, and method for the next node.","tips":[],"docsHref":"/docs/nodes/webhook","why":"Receives one normalized payload from the source system through an allowed webhook trigger."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.userId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_notes_doc","type":"custom","position":{"x":420,"y":395},"data":{"icon":"FileText","type":"google_doc","label":"Read Notes Doc","category":"data","config":{"operation":"read","documentId":"REPLACE_WITH_NOTES_DOC_ID","format":"markdown"},"notes":{"family":"Data","what":"Read from or write to a Google Doc — create documents or update them automatically","overview":"Read, overwrite (write), create, or append content in Google Docs. Read extracts plain text only; the Output Format \"Markdown\" option is currently a label and does not actually convert formatting.","tips":["Get Document ID from the Google Docs URL: https://docs.google.com/document/d/DOCUMENT_ID/edit â€” you can paste the full Document URL, or just the DOCUMENT_ID into Document ID","Read only extracts plain text â€” there is no table/list structure in the output, and choosing Markdown does not convert formatting","Write deletes ALL existing content before inserting the new text â€” use Append to add without removing what is already there","Create makes a brand-new document and returns documentUrl to share it","Always connect a Google account first via Connections","For read/write/append, ensure the connected Google account has access to the target document"],"docsHref":"/docs/nodes/google_doc","why":"Lets the agent consult the user notes document before deciding what to remember or answer."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are a personal assistant with long-term memory. If the user asks you to remember something, include a noteToSave field; otherwise answer naturally. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"user","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"google_doc_append_note","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"FileText","type":"google_doc","label":"Append Note if Needed","category":"data","config":{"operation":"append","documentId":"REPLACE_WITH_NOTES_DOC_ID","content":"{{input.noteToSave}}"},"notes":{"family":"Data","what":"Read from or write to a Google Doc — create documents or update them automatically","overview":"Read, overwrite (write), create, or append content in Google Docs. Read extracts plain text only; the Output Format \"Markdown\" option is currently a label and does not actually convert formatting.","tips":["Get Document ID from the Google Docs URL: https://docs.google.com/document/d/DOCUMENT_ID/edit â€” you can paste the full Document URL, or just the DOCUMENT_ID into Document ID","Read only extracts plain text â€” there is no table/list structure in the output, and choosing Markdown does not convert formatting","Write deletes ALL existing content before inserting the new text â€” use Append to add without removing what is already there","Create makes a brand-new document and returns documentUrl to share it","Always connect a Google account first via Connections","For read/write/append, ensure the connected Google account has access to the target document"],"docsHref":"/docs/nodes/google_doc","why":"Persists explicit remember-this requests into the user notes document."}}},{"id":"telegram_reply","type":"custom","position":{"x":1700,"y":300},"data":{"icon":"Send","type":"telegram","label":"Reply in Telegram","category":"output","config":{"chatId":"{{input.chatId}}","text":"{{input.message}}"},"notes":{"family":"Communication","what":"Sends messages to a Telegram chat or bot conversation","overview":"Send Telegram text messages, media URLs, and message edits through a saved Telegram Bot Token connection. Use it for Telegram bot replies, support alerts, report delivery, approval buttons, and status updates.","tips":["Create the bot with @BotFather, then save the Telegram Bot Token in Connections","Use {{$json.chatId}} and {{$json.messageId}} from Telegram Trigger to reply in the same chat","Choose send_message for text, send_photo plus Media URL for images, and edit_message when updating a previous bot message","For media message types, use a public HTTPS Media URL that Telegram can fetch without signing in","Connect downstream service accounts separately; Telegram credentials only authorize Telegram sends"],"docsHref":"/docs/nodes/telegram","why":"Sends the assistant response back to the Telegram chat."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_webhook_intake_memory_context","source":"webhook_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_webhook_intake_tool_notes_doc","source":"webhook_intake","target":"tool_notes_doc"},{"id":"e_4_tool_notes_doc_ai_agent","source":"tool_notes_doc","target":"ai_agent","targetHandle":"tool"},{"id":"e_5_webhook_intake_ai_agent","source":"webhook_intake","target":"ai_agent","targetHandle":"userInput"},{"id":"e_6_ai_agent_js_parse_agent","source":"ai_agent","target":"js_parse_agent"},{"id":"e_7_js_parse_agent_google_doc_append_note","source":"js_parse_agent","target":"google_doc_append_note"},{"id":"e_8_google_doc_append_note_telegram_reply","source":"google_doc_append_note","target":"telegram_reply"}]$tpl$::jsonb, $tpl$Intermediate$tpl$,
  20, ARRAY[$tpl$telegram$tpl$,$tpl$memory$tpl$,$tpl$google-docs$tpl$,$tpl$assistant$tpl$,$tpl$ai-agent$tpl$]::text[],
  false, true, 0, 2, now(), now()
)
