-- Website Chat Widget Support Agent (NEW)
INSERT INTO templates (
  id, name, description, category, nodes, edges, difficulty,
  estimated_setup_time, tags, is_featured, is_active, use_count, version,
  created_at, updated_at
) VALUES (
  $tpl$93000000-0000-4000-8000-000000000003$tpl$, $tpl$Website Chat Widget Support Agent$tpl$, $tpl$Answer website chat questions with a lightweight knowledge-base lookup and reply in the active chat session.$tpl$, $tpl$AI Agent$tpl$,
  $tpl$[{"id":"chat_intake","type":"custom","position":{"x":100,"y":300},"data":{"icon":"Box","type":"chat_trigger","label":"Receive Chat Message","category":"triggers","config":{},"notes":{"family":"Triggers","what":"Starts your workflow when someone types a message in a chat interface","overview":"Starting node that runs when someone sends a message through the CtrlChecks chat interface for an active workflow. The node panel has no setup fields today; the chat page supplies the message and session details at runtime.","tips":["Use as the first node in chatbot, assistant, support intake, or guided request workflows","Map {{$json.message}} into AI Agent or HTTP Request when the next step needs the visitor question","Use Chat Send after the answer is prepared; it can read {{$json.sessionId}} from the connected Chat Trigger output","The workflow must be active before the public chat URL accepts messages","Downstream app nodes such as Slack, Gmail, CRM, or database actions still need their own account connection"],"docsHref":"/docs/nodes/chat_trigger","why":"Starts the agent from one chat message and preserves the session data for replies."}}},{"id":"memory_context","type":"custom","position":{"x":420,"y":205},"data":{"icon":"Brain","type":"memory","label":"Conversation Memory","category":"ai","config":{"sessionId":"{{input.sessionId}}","maxMessages":20},"notes":{"family":"AI","what":"Saves conversation history so your AI can remember things across multiple steps","overview":"Passes sessionId, context, and incoming messages forward for AI workflows. The current runtime does not store, retrieve, clear, search, expire, or limit memory; those visible controls are legacy no-ops.","tips":["Use Session ID and Context as the real data passed to downstream AI steps.","Store, Retrieve, Clear, and Search currently behave the same.","TTL, Memory Type, and Max Messages are ignored by the current executor.","No memory or searchResults field is produced."],"docsHref":"/docs/nodes/memory","why":"Provides the agent a stable session key and recent-context window for multi-turn conversations."}}},{"id":"tool_kb_lookup","type":"custom","position":{"x":420,"y":395},"data":{"icon":"Globe","type":"http_request","label":"Search Knowledge Base","category":"http_api","config":{"url":"https://api.example.com/kb/search?q={{input.message}}","method":"GET","timeout":10000},"notes":{"family":"HTTP & API","what":"Calls any web URL and gets data back — your universal connector to the internet","overview":"Call an external API or webhook, optionally adding headers, query parameters, body data, and a timeout.","tips":[],"docsHref":"/docs/nodes/http_request","why":"Gives the agent current website FAQ context before it answers the visitor."}}},{"id":"ai_agent","type":"custom","position":{"x":740,"y":300},"data":{"icon":"Bot","type":"ai_agent","label":"AI Agent","category":"ai","config":{"model":"gemini-3.5-flash","temperature":0.2,"userInput":"Process this workflow input and any attached tool results: {{input}}","systemPrompt":"You are a concise website assistant. Use the knowledge-base lookup for product or pricing questions and keep answers under 100 words. Return ONLY JSON with the fields named in this workflow.","outputFormat":"json","memoryScope":"conversation","requireApprovalFor":"destructive"},"notes":{"family":"AI","what":"An autonomous AI brain that reasons, makes decisions, and uses tools on your behalf","overview":"Runs one prompt-driven AI step. The runtime extracts userInput from this node or upstream message-like fields, infers the provider from Model, calls the LLM adapter, and packages response_text plus optional structured fields.","tips":[],"docsHref":"/docs/nodes/ai_agent","why":"Applies the source AI-agent prompt to the current request and attached read-side context, returning structured JSON for deterministic downstream steps."}}},{"id":"js_parse_agent","type":"custom","position":{"x":1060,"y":300},"data":{"icon":"Code","type":"javascript","label":"Parse Agent JSON","category":"data","config":{"code":"const raw = input.response_text || input.output || input.response || input.text || input.content || \"\";\nlet parsed = {};\ntry {\n  const match = String(raw).match(/\\{[\\s\\S]*\\}/);\n  parsed = match ? JSON.parse(match[0]) : {};\n} catch (error) {\n  parsed = {};\n}\nconst message = parsed.message || parsed.reply || parsed.emailBody || parsed.body || parsed.summary || String(raw);\nreturn { ...input, ...parsed, responseText: String(raw), message };","timeout":5000},"notes":{"family":"Data","what":"Writes and runs any JavaScript you like to transform or process your data","overview":"Run sandboxed JavaScript once against the current workflow data and return the transformed value for downstream nodes.","tips":["Always return the value the next node should receive","Default timeout is 5000ms and runtime caps at 30000ms","Use Output Schema such as {\"type\":\"object\"} only as a top-level shape hint","JavaScript has no credentials; connect downstream service node accounts separately","Do not paste API keys, tokens, or passwords into code"],"docsHref":"/docs/nodes/javascript","why":"Turns the agent response into top-level fields before any branch or output node reads it."}}},{"id":"chat_reply","type":"custom","position":{"x":1380,"y":300},"data":{"icon":"Send","type":"chat_send","label":"Reply in Chat","category":"output","config":{"message":"{{input.message}}"},"notes":{"family":"Database","what":"Sends a reply in a chat conversation — works with a chat trigger to create a bot","overview":"","tips":[],"docsHref":null,"why":"Returns the answer to the same chat session that asked the question."}}}]$tpl$::jsonb, $tpl$[{"id":"e_1_chat_intake_memory_context","source":"chat_intake","target":"memory_context"},{"id":"e_2_memory_context_ai_agent","source":"memory_context","target":"ai_agent","targetHandle":"memory"},{"id":"e_3_chat_intake_tool_kb_lookup","source":"chat_intake","target":"tool_kb_lookup"},{"id":"e_4_t